  }
  if (
    tool.startsWith("getOption") ||
    tool.includes("OpenInterest") ||
    tool.includes("Pain") ||
    tool.includes("PutCall") ||
    tool.includes("Greek")
  ) {
    return "OPTIONS";
  }
  if (tool.includes("Historical") || tool.includes("Intraday")) {
    return "HISTORICAL";
  }
