          trace(
            {
              name: workflow,
              kind: "WORKFLOW",
              input: options.input ?? {},
              attributes: spanAttributes(ref),
            },
            body,
          ),
      ),
    (active) =>
      withUsage(async (totals) => {
        if (active) ref.carrier = traceCarrier();
        try {
          return await fn(ref);
        } finally {
          setUsage(active, totals, Date.now() - startedAt);
        }
      }),
  );
}

/** Opens the root and returns the ref (for an API route that only enqueues work). */
export function startWorkflow(
  workflow: WorkflowName,
  options: WorkflowOptions,
): Promise<WorkflowRef> {
  return runWorkflow(workflow, options, async (ref) => ref);
}

/**
 * Runs one Inngest step (or any remote unit of work) inside the run's trace as
 * a CHAIN span, then flushes. Used by `neatlogsInngestMiddleware` for every
 * `step.run` whose event carries a `trace` ref.
 */
export async function continueWorkflow<T>(
  ref: WorkflowRef,
  stepName: string,
  fn: () => Promise<T>,
): Promise<T> {
  const startedAt = Date.now();
  try {
    return await failOpen(
      stepName,
      (body) =>
        extractTraceContext(ref.carrier, () =>
          identify(
            { endUserId: ref.endUserId, ...(ref.sessionId ? { sessionId: ref.sessionId } : {}) },
            () =>
              trace(
                {
                  name: `step.${stepName}`,
                  kind: "CHAIN",
                  attributes: spanAttributes(ref, [`step:${stepName}`]),
                },
                body,
              ),
          ),
        ),
      (active) =>
        withUsage(async (totals) => {
          try {
            return await fn();
          } finally {
            setUsage(active, totals, Date.now() - startedAt);
          }
        }),
    );
  } finally {
    await flush().catch((error: unknown) => warn("flush failed", error));
  }
}

// ── Agent / tool / embedding spans ──

function wrapSpan<TArgs extends unknown[], TReturn>(
  options: Parameters<typeof span>[0],
  fn: (...args: TArgs) => TReturn,
): (...args: TArgs) => TReturn {
  let traced: (...args: TArgs) => TReturn;
  try {
    traced = span(options, fn);
  } catch (error) {
    warn(`could not wrap ${options.name}`, error);
    return fn;
  }
  return (...args: TArgs) => {
    try {
      return traced(...args);
    } catch (error) {
      // `fn` is async, so its own errors reject; a sync throw comes from the SDK.
      warn(`${options.name}: tracing failed, running untraced`, error);
/**
 * Inngest middleware: every `step.run` attempt of a function whose event carries
 * a `trace` ref (see `WorkflowRef`) runs inside that run's Neatlogs trace as a
 * CHAIN span named after the step, and flushes when the step ends.
 *
 * Covers `onFailure` handlers too (their event wraps the original in
 * `data.event`). Events without a `trace` ref run untraced at the step level;
 * their agent / tool spans then start their own traces.
 */

import { Middleware } from "inngest";
import {
  continueWorkflow,
  workflowRefFromEvent,
} from "@/lib/observability/neatlogs";

export class NeatlogsInngestMiddleware extends Middleware.BaseMiddleware {
  readonly id = "neatlogs";

  override async wrapStepHandler({
    ctx,
    next,
    stepInfo,
  }: Middleware.WrapStepHandlerArgs): Promise<unknown> {
    const ref = stepInfo.stepType === "run" ? workflowRefFromEvent(ctx.event) : null;
    if (!ref) {
      return next();
    }
    return continueWorkflow(ref, stepInfo.options.id, () => next());
  }
}

