cat > .tmp-probe.mjs <<'EOF'
import "dotenv/config";
import { getJson, getAccount, getJsonBySearchId } from "serpapi";
import { Firecrawl } from "firecrawl";
const key = process.env.SERPAPI_API_KEY;
const acct = async (l) => { const a = await getAccount({ api_key: key }); console.log(l, JSON.stringify({ this_month_usage: a.this_month_usage, last_hour_searches: a.last_hour_searches, total_searches_left: a.total_searches_left })); };
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
await acct("account before:");
const q = { engine: "google", q: "nifty 50 index methodology", num: 10, api_key: key };
for (const label of ["call 1", "call 2 (same params)"]) {
  const t0 = new Date();
  const r = await getJson(q);
  const m = r.search_metadata;
  console.log(label, "requestStart", t0.toISOString(), "meta:", JSON.stringify({ id: m.id, status: m.status, created_at: m.created_at, processed_at: m.processed_at, total_time_taken: m.total_time_taken, keys: Object.keys(m) }), "organic:", r.organic_results?.length ?? 0);
  if (label === "call 1") { var firstId = m.id; await sleep(4000); }
}
const arch = await getJsonBySearchId(firstId, { api_key: key });
console.log("archive by id:", JSON.stringify({ id: arch.search_metadata?.id, status: arch.search_metadata?.status, keys: Object.keys(arch.search_metadata ?? {}) }));
await sleep(5000);
await acct("account after:");

const fc = new Firecrawl({ apiKey: process.env.FIRECRAWL_API_KEY });
const before = await fc.getCreditUsage().catch((e) => ({ err: e.message }));
console.log("firecrawl credit usage before:", JSON.stringify(before));
const doc = await fc.scrape("https://example.com", { formats: ["markdown"], onlyMainContent: true });
const md = doc.metadata ?? {};
console.log("firecrawl scrape metadata:", JSON.stringify({ creditsUsed: md.creditsUsed, cacheState: md.cacheState, cachedAt: md.cachedAt, statusCode: md.statusCode, proxyUsed: md.proxyUsed, contentType: md.contentType, metaKeys: Object.keys(md) }), "docKeys:", Object.keys(doc));
const doc404 = await fc.scrape("https://example.com/definitely-missing-page-xyz", { formats: ["markdown"], onlyMainContent: true }).catch((e) => ({ thrown: e.message }));
console.log("firecrawl 404:", JSON.stringify(doc404.thrown ? doc404 : { statusCode: doc404.metadata?.statusCode, creditsUsed: doc404.metadata?.creditsUsed, hasMarkdown: Boolean(doc404.markdown) }));
await sleep(5000);
console.log("firecrawl credit usage after:", JSON.stringify(await fc.getCreditUsage().catch((e) => ({ err: e.message }))));
EOF
node ./.tmp-probe.mjs 2>&1 | grep -v "^◇"; rm -f ./.tmp-probe.mjs

